content = '''"""Tests for milestone m3: @cachedmethod raises DeprecationWarning when key returns None."""

import warnings


def test_cachedmethod_none_key_raises_deprecation_warning():
    """Test that @cachedmethod raises DeprecationWarning when key function returns None."""
    import cachetools
    from cachetools import cachedmethod

    class MyClass:
        def __init__(self):
            self._cache = {}

        @cachedmethod(lambda self: self._cache)
        def get_value(self, flag):
            if not flag:
                return "skipped"
            return "computed"

    obj = MyClass()

    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")
        result = obj.get_value(False)
        deprecation_warnings = [x for x in w if issubclass(x.category, DeprecationWarning)]
        assert len(deprecation_warnings) >= 1, (
            f"Expected at least one DeprecationWarning when key returns None, "
            f"but got: {[str(x.message) for x in w]}"
        )


def test_cachedmethod_none_key_does_not_cache():
    """Test that when key returns None, the result is NOT added to the cache."""
    import cachetools
    from cachetools import cachedmethod

    class MyClass:
        def __init__(self):
            self._cache = {}

        @cachedmethod(lambda self: self._cache)
        def compute(self, flag):
            if flag:
                return "result"
            return "none_result"

    obj = MyClass()

    with warnings.catch_warnings(record=True):
        warnings.simplefilter("always")
        obj.compute(True)
        obj.compute(False)

    # Only one entry should be in cache (for True case), None key should not be cached
    assert len(obj._cache) == 1


def test_cachedmethod_none_key_still_executes():
    """Test that the method body still executes even when key returns None."""
    import cachetools
    from cachetools import cachedmethod

    class MyClass:
        def __init__(self):
            self._cache = {}
            self.executed = False

        @cachedmethod(lambda self: self._cache)
        def compute(self, flag):
            self.executed = True
            if flag:
                return "result"
            return "none_result"

    obj = MyClass()

    with warnings.catch_warnings(record=True):
        warnings.simplefilter("always")
        result = obj.compute(False)

    # Method body should have executed
    assert obj.executed is True
    # Should still return the computed value
    assert result == "none_result"
'''

